-- =====================================================================
-- VITAL CLINIC — Seed de população (SQL puro, pronto para phpMyAdmin)
-- Simula o uso diário real de uma rede com várias clínicas: médicos,
-- administradores, dezenas de pacientes e um histórico amplo de
-- consultas em diferentes status, com datas passadas e futuras.
--
-- Como rodar:
--   phpMyAdmin: selecione o banco 'vitalclinic' -> aba SQL -> cole
--   este arquivo inteiro -> Executar.
--   Linha de comando: mysql -u root -p vitalclinic < seed_populacao.sql
--
-- Este script é ADITIVO: nunca apaga nem altera dados existentes.
-- Todos os registros usam e-mail terminado em '@seed4.local' e CNPJ
-- com prefixo '99.' para ficarem fáceis de identificar/remover depois:
--   DELETE FROM users   WHERE email LIKE '%@seed4.local';
--   DELETE FROM clinics WHERE cnpj  LIKE '99.%';
--   (registros dependentes somem sozinhos por ON DELETE CASCADE)
--
-- Senha de login de todos os usuários gerados: "password"
-- =====================================================================

